import json
from pathlib import Path

seed = json.loads(Path("src/data/seed.json").read_text())

# Count entries with missing source citations in key fields
cited_fields = [
    "battery_kwh_total", "battery_kwh_usable", "range_km", 
    "dc_charge_kw_max", "ac_charge_kw_max", "msrp_cad",
    "weight_kg", "cargo_l_seats_up"
]

print("=== CITATION COMPLETENESS ===\n")
missing_sources = {}
for v in seed["vehicles"]:
    vehicle_id = v["id"]
    for field in cited_fields:
        cv = v.get(field)
        if cv is None:
            continue
        if isinstance(cv, dict):
            if cv.get("value") is not None and cv.get("source") is None:
                if vehicle_id not in missing_sources:
                    missing_sources[vehicle_id] = []
                missing_sources[vehicle_id].append(field)

if missing_sources:
    print(f"Vehicles with missing source citations:")
    for vid, fields in sorted(missing_sources.items()):
        print(f"  {vid}: {', '.join(fields)}")
else:
    print("✓ All cited fields have sources (or are null).")

print("\n=== LOW-CONFIDENCE ENTRIES ===\n")
for v in seed["vehicles"]:
    if v.get("overall_confidence") == "Low":
        print(f"Vehicle: {v['id']}")
        print(f"  Model: {v['model']} ({v['generation_label']})")
        print(f"  Notes: {v.get('notes', 'N/A')}")

        # Show which fields are null
        null_fields = []
        for field in ["battery_kwh_total", "battery_kwh_usable", "range_km", 
                      "dc_charge_kw_max", "weight_kg", "msrp_cad"]:
            cv = v.get(field)
            if cv is not None and isinstance(cv, dict) and cv.get("value") is None:
                null_fields.append(field)
        if null_fields:
            print(f"  Null fields: {', '.join(null_fields)}")
        print()

print("=== CHARGING CURVE COVERAGE ===\n")
no_curve = []
for v in seed["vehicles"]:
    curve = v.get("charging_curve_20c", [])
    if not curve:
        no_curve.append(v["id"])

print(f"Vehicles with NO charging curve: {len(no_curve)}")
for vid in no_curve:
    v = next((x for x in seed["vehicles"] if x["id"] == vid), {})
    print(f"  {vid} ({v.get('model', '?')})")

print("\n=== THERMAL PROFILE COMPLETENESS ===\n")
thermal_fields = ["cold_derate_curve", "hvac_draw_kw_by_temp", "precon_draw_kw"]
thermal_count = 0
for field in thermal_fields:
    count = sum(1 for v in seed["vehicles"] if field in v and v[field] is not None)
    print(f"  {field}: {count}/20 vehicles")
    if count > 0:
        thermal_count += count

if thermal_count == 0:
    print("\n⚠ No advanced thermal fields populated. All vehicles fall back to defaults.")

print("\n=== DISTINCT SOURCE DOMAINS ===\n")
sources = set()
for v in seed["vehicles"]:
    for field in v.values():
        if isinstance(field, dict) and "source" in field:
            src = field["source"]
            if src and "url" in src:
                domain = src["url"].split("/")[2] if "/" in src["url"] else "unknown"
                sources.add(domain)

print(f"Found {len(sources)} distinct source domains:")
for src in sorted(sources):
    print(f"  {src}")

