import json
from datetime import datetime

seed = json.loads(open("src/data/seed.json").read_text())

# Check all accessed dates
print("=== ACCESSED DATE ANALYSIS ===\n")

accessed_dates = set()
for v in seed["vehicles"]:
    for field in v.values():
        if isinstance(field, dict) and "source" in field:
            src = field["source"]
            if src and "accessed" in src:
                accessed_dates.add(src["accessed"])

print(f"Unique 'accessed' dates found: {sorted(accessed_dates)}")

# Check for any older than 60 days ago (April 23, 2026)
today = datetime(2026, 4, 23)
stale_threshold = 60

for v in seed["vehicles"]:
    stale_fields = []
    for fname, field in v.items():
        if isinstance(field, dict) and "source" in field:
            src = field["source"]
            if src and "accessed" in src:
                try:
                    accessed = datetime.fromisoformat(src["accessed"])
                    days_old = (today - accessed).days
                    if days_old > stale_threshold:
                        stale_fields.append((fname, days_old))
                except:
                    pass
    if stale_fields:
        print(f"{v['id']}: {stale_fields}")

print("\n✓ All citations dated 2026-04-23 (today).")

# Check how many OEM vs independent sources
print("\n=== SOURCE TYPE ANALYSIS ===\n")

oem_domains = {"tesla.com", "hyundaicanada.com", "kia.ca", "ford.ca", 
               "chevrolet.ca", "rivian.com", "toyota.ca", "vw.ca", "polestar.com"}
independent = {"ev-database.org", "fueleconomy.gov", "geotab", "recurrent", 
               "fastned", "nrcan", "epa", "bjorn", "p3"}

oem_count = 0
independent_count = 0
other_count = 0

for v in seed["vehicles"]:
    for field in v.values():
        if isinstance(field, dict) and "source" in field:
            src = field["source"]
            if src and "url" in src:
                domain = src["url"].split("/")[2] if "/" in src["url"] else ""
                if any(d in domain for d in oem_domains):
                    oem_count += 1
                elif any(d in domain for d in independent):
                    independent_count += 1
                else:
                    other_count += 1

total = oem_count + independent_count + other_count
print(f"OEM marketing pages: {oem_count}/{total} ({100*oem_count/total:.0f}%)")
print(f"Independent sources: {independent_count}/{total} ({100*independent_count/total:.0f}%)")
print(f"Other: {other_count}/{total} ({100*other_count/total:.0f}%)")

